import re
from calendar import monthrange
from datetime import datetime, timedelta

_MONTH_NAMES = {
    name: index
    for index, name in enumerate(
        ("JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"),
        start=1,
    )
}
_DOW_NAMES = {
    name: index
    for index, name in enumerate(("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"))
}
_DIGITS = re.compile(r"[0-9]+")
_SEPARATOR = re.compile(r"[ \t]+")


def _parse_value(token, low, high, names):
    if _DIGITS.fullmatch(token):
        value = int(token)
    elif names is not None and token.isascii() and token.upper() in names:
        value = names[token.upper()]
    else:
        raise ValueError(f"invalid value: {token!r}")
    if not low <= value <= high:
        raise ValueError(f"value out of range: {token!r}")
    return value


def _parse_range(text, low, high, names):
    bounds = text.split("-")
    if len(bounds) != 2:
        raise ValueError(f"invalid range: {text!r}")
    start = _parse_value(bounds[0], low, high, names)
    end = _parse_value(bounds[1], low, high, names)
    if start > end:
        raise ValueError(f"descending range: {text!r}")
    return start, end


def _parse_field(text, low, high, names):
    values = set()
    for item in text.split(","):
        if item == "":
            raise ValueError("empty item")
        step = 1
        if "/" in item:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError(f"invalid item: {item!r}")
            base, step_text = parts
            if not _DIGITS.fullmatch(step_text):
                raise ValueError(f"invalid step: {item!r}")
            step = int(step_text)
            if step < 1:
                raise ValueError(f"step must be >= 1: {item!r}")
            if base == "*":
                start, end = low, high
            elif "-" in base:
                start, end = _parse_range(base, low, high, names)
            else:
                raise ValueError(f"step without range: {item!r}")
        elif item == "*":
            start, end = low, high
        elif "-" in item:
            start, end = _parse_range(item, low, high, names)
        else:
            start = end = _parse_value(item, low, high, names)
        values.update(range(start, end + 1, step))
    return values


def _parse_expression(expression):
    if not isinstance(expression, str):
        raise ValueError("expression must be a string")
    fields = _SEPARATOR.split(expression.strip(" \t"))
    if len(fields) != 5:
        raise ValueError("expression must have exactly 5 fields")
    minutes = _parse_field(fields[0], 0, 59, None)
    hours = _parse_field(fields[1], 0, 23, None)
    days = _parse_field(fields[2], 1, 31, None)
    months = _parse_field(fields[3], 1, 12, _MONTH_NAMES)
    weekdays_raw = _parse_field(fields[4], 0, 7, _DOW_NAMES)
    weekdays = {0 if value == 7 else value for value in weekdays_raw}
    day_is_star = fields[2] == "*"
    weekday_is_star = fields[4] == "*"
    return minutes, hours, days, months, weekdays, day_is_star, weekday_is_star


def next_run(expression: str, after: datetime) -> datetime | None:
    (
        minutes,
        hours,
        days,
        months,
        weekdays,
        day_is_star,
        weekday_is_star,
    ) = _parse_expression(expression)

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        return None

    sorted_minutes = sorted(minutes)
    sorted_hours = sorted(hours)
    sorted_months = sorted(months)
    last_year = min(after.year + 10, 9999)
    start_date = (start.year, start.month, start.day)

    for year in range(start.year, last_year + 1):
        for month in sorted_months:
            if (year, month) < (start.year, start.month):
                continue
            days_in_month = monthrange(year, month)[1]
            for day in range(1, days_in_month + 1):
                if (year, month, day) < start_date:
                    continue
                day_match = day in days
                # cron の曜日: 0 = 日曜。Python の weekday() は 0 = 月曜
                weekday_match = ((datetime(year, month, day).weekday() + 1) % 7) in weekdays
                if day_is_star and weekday_is_star:
                    matched = True
                elif day_is_star:
                    matched = weekday_match
                elif weekday_is_star:
                    matched = day_match
                else:
                    matched = day_match or weekday_match
                if not matched:
                    continue
                same_day = (year, month, day) == start_date
                for hour in sorted_hours:
                    if same_day and hour < start.hour:
                        continue
                    for minute in sorted_minutes:
                        if same_day and hour == start.hour and minute < start.minute:
                            continue
                        return datetime(year, month, day, hour, minute)
    return None
